      "imageSrc": "../data/archive/20261010-green-canopy-d6b3ceef/original.jpg",
      "thumbSrc": "../data/archive/20261010-green-canopy-d6b3ceef/thumb.jpg",
      "previewSrc": "../data/archive/20261010-green-canopy-d6b3ceef/preview.jpg",
