      "imageSrc": "../data/archive/20261008-glass-rhythm-85530b0c/original.jpg",
      "thumbSrc": "../data/archive/20261008-glass-rhythm-85530b0c/thumb.jpg",
      "previewSrc": "../data/archive/20261008-glass-rhythm-85530b0c/preview.jpg",
      "imageFile": "original.jpg",
