      "imageSrc": "../data/archive/20261007-street-pipes-f64f87ae/original.jpg",
      "thumbSrc": "../data/archive/20261007-street-pipes-f64f87ae/thumb.jpg",
      "previewSrc": "../data/archive/20261007-street-pipes-f64f87ae/preview.jpg",
