      "imageSrc": "../data/archive/20260824-164909-bamboo-rhythm/original.jpg",
      "thumbSrc": "../data/archive/20260824-164909-bamboo-rhythm/thumb.jpg",
      "previewSrc": "../data/archive/20260824-164909-bamboo-rhythm/preview.jpg",
