      "imageSrc": "../data/archive/20260710-131526-green-close-graduation-portrait/original.jpg",
      "thumbSrc": "../data/archive/20260710-131526-green-close-graduation-portrait/thumb.jpg",
      "previewSrc": "../data/archive/20260710-131526-green-close-graduation-portrait/preview.jpg",
